-- =====================================================================
-- V2：评估报告持久化（《报告持久化与导出-实施计划》阶段 1）
-- 报告首次查看时生成并落库（ensure 模式），之后直接读库不再重复调 LLM。
-- report_json 存完整结构化 JSON（覆盖矩阵/结论/薄弱点），前端直接渲染；
-- Markdown / PDF 是导出时的呈现格式，由前端转换，不落库。
-- 一场会话只保留最新一份报告（uk_report_session），重新生成 version+1 覆盖。
-- =====================================================================

CREATE TABLE assessment_report (
    -- GENERATED BY DEFAULT AS IDENTITY：id 由数据库自增生成（Hibernate GenerationType.IDENTITY
    -- 插入时不传 id 列）。教训（2026-10-23 实测踩坑）：只写 int8 NOT NULL 会让 insert 报
    -- "null value in column id violates not-null constraint"。V1 基线脚本里各表的 id 也是裸
    -- int8——存量库没暴露是因为那些表是 ddl-auto 时代建的（真有 identity），V1 在存量库只打
    -- 基线标记从不执行；但全新库从 V1 建表会踩同一个坑（V1 的修复另行处理，见实施计划风险节）。
    id int8 NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    session_id varchar(64) NOT NULL,
    candidate_id varchar(64) NOT NULL,
    report_json text NOT NULL,
    version int4 NOT NULL DEFAULT 1,
    generated_at timestamp NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_report_session UNIQUE (session_id)
);
